import java.util.*;

class Solution {
    static int lengthOfLongestSubstring(String s) {
        Map<Character, Integer> ultima = new HashMap<>();
        int best = 0, ini = 0;
        for (int fim = 0; fim < s.length(); fim++) {
            char c = s.charAt(fim);
            if (ultima.containsKey(c) && ultima.get(c) >= ini)
                ini = ultima.get(c) + 1;
            ultima.put(c, fim);
            best = Math.max(best, fim - ini + 1);
        }
        return best;
    }
}

