import java.util.*;

class Solution {
    static int[][] insert(int[][] intervals, int[] novo) {
        List<int[]> res = new ArrayList<>();
        int i = 0, n = intervals.length;
        while (i < n && intervals[i][1] < novo[0]) res.add(intervals[i++]);
        int[] m = novo.clone();
        while (i < n && intervals[i][0] <= m[1]) {
            m[0] = Math.min(m[0], intervals[i][0]);
            m[1] = Math.max(m[1], intervals[i][1]);
            i++;
        }
        res.add(m);
        while (i < n) res.add(intervals[i++]);
        return res.toArray(new int[0][]);
    }
}

