class Solution {
    static int[] nextPermutation(int[] nums) {
        int i = nums.length - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) i--;
        if (i >= 0) {
            int j = nums.length - 1;
            while (nums[j] <= nums[i]) j--;
            troca(nums, i, j);
        }
        reverter(nums, i + 1, nums.length - 1);
        return nums;
    }
    static void troca(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }
    static void reverter(int[] a, int i, int j) { while (i < j) troca(a, i++, j--); }
}

