class Solution {
    static int search(int[] nums, int alvo) {
        int lo = 0, hi = nums.length - 1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (nums[mid] == alvo) return mid;
            if (nums[lo] <= nums[mid]) {
                if (nums[lo] <= alvo && alvo < nums[mid]) hi = mid - 1;
                else lo = mid + 1;
            } else {
                if (nums[mid] < alvo && alvo <= nums[hi]) lo = mid + 1;
                else hi = mid - 1;
            }
        }
        return -1;
    }
}

