import java.util.*;

class Solution {
    static List<Integer> spiralOrder(int[][] m) {
        List<Integer> res = new ArrayList<>();
        if (m.length == 0) return res;
        int cima = 0, baixo = m.length - 1, esq = 0, dir = m[0].length - 1;
        while (cima <= baixo && esq <= dir) {
            for (int j = esq; j <= dir; j++) res.add(m[cima][j]);
            cima++;
            for (int i = cima; i <= baixo; i++) res.add(m[i][dir]);
            dir--;
            if (cima <= baixo) { for (int j = dir; j >= esq; j--) res.add(m[baixo][j]); baixo--; }
            if (esq <= dir) { for (int i = baixo; i >= cima; i--) res.add(m[i][esq]); esq++; }
        }
        return res;
    }
}

